import{_ as o,C as r,o as s,c as e,j as i,E as l,a as d,a2 as n}from"./chunks/framework.C21TwvGF.js";const z=JSON.parse('{"title":"3-hafta (Mentor)","description":"","frontmatter":{"title":"3-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (IoT)","link":"/mentor/9-sinf-iot/"},"n":3,"bob":"II-bob · Elektronika va Arduino bilan interaktiv interfeyslar","lessons":[{"g":7,"title":"7-dars: Elektron sxema asosida ikki LED lampaning ishlash prinsipi va ulanishi","lead":"Elektron sxema asosida ikki LED lampaning ishlash prinsipi va ulanishi","link":"/mentor/9-sinf-iot/hafta-03/dars-1","slide":"/slaydlar/9-sinf-iot/hafta-03/dars-1.html","test":"/slaydlar/9-sinf-iot/hafta-03/dars-1-test.html"},{"g":8,"title":"8-dars: Arduino UNO yordamida LED indikatorlari va push-button bilan ishlash (1-qism)","lead":"Arduino UNO yordamida LED indikatorlari va push-button bilan ishlash (1-qism)","link":"/mentor/9-sinf-iot/hafta-03/dars-2","slide":"/slaydlar/9-sinf-iot/hafta-03/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-03/dars-2-test.html"},{"g":9,"title":"9-dars: Arduino UNO yordamida LED indikatorlari va push-button bilan interaktiv interfeys (2-qism)","lead":"Arduino UNO yordamida LED indikatorlari va push-button bilan interaktiv interfeys (2-qism)","link":"/mentor/9-sinf-iot/hafta-03/dars-3","slide":"/slaydlar/9-sinf-iot/hafta-03/dars-3.html","test":"/slaydlar/9-sinf-iot/hafta-03/dars-3-test.html"}],"test":"/slaydlar/9-sinf-iot/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-iot/hafta-03/index.md","filePath":"mentor/9-sinf-iot/hafta-03/index.md"}'),h={name:"mentor/9-sinf-iot/hafta-03/index.md"},u={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},b={class:"blk"},g={id:"baholash-mezoni",tabindex:"-1"};function k(c,a,v,q,y,f){const t=r("Icon");return s(),e("div",null,[i("div",u,[i("h2",m,[l(t,{name:"house"}),a[0]||(a[0]=d(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=n('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_7-dars-elektron-sxema-asosida-ikki-led-lampaning-ishlash-prinsipi-va-ulanishi" tabindex="-1">7-dars: Elektron sxema asosida ikki LED lampaning ishlash prinsipi va ulanishi <a class="header-anchor" href="#_7-dars-elektron-sxema-asosida-ikki-led-lampaning-ishlash-prinsipi-va-ulanishi" aria-label="Permalink to &quot;7-dars: Elektron sxema asosida ikki LED lampaning ishlash prinsipi va ulanishi&quot;">​</a></h2><ol><li>Tinkercad-da Arduino Uno, Breadboard, 2 ta 220 Om rezistor hamda Qizil va Yashil LED dan iborat mustaqil parallel sxemani yig&#39;ing (Qizil — Pin 9, Yashil — Pin 11).</li><li>C++ tilida yo&#39;l harakati xavfsizligi mayoqchasini (Traffic Flasher) dasturlang: <ul><li>Qizil LED 3 marta tez miltillaydi (har biri 150 ms yoniq, 150 ms o&#39;chiq);</li><li>Yashil LED 3 marta tez miltillaydi (har biri 150 ms yoniq, 150 ms o&#39;chiq);</li><li>Ikkala LED 1 soniyaga o&#39;chib tanaffus qiladi va tsikl takrorlanadi.</li></ul></li><li>Nima uchun 3 ta LED ni 5V manbaga ketma-ket ulaganda ular yonmasligini kuchlanishlar yig&#39;indisi formulasi ($U = U_1 + U_2 + U_3$) orqali asoslab bering.</li></ol><hr><h2 id="_8-dars-arduino-uno-yordamida-led-indikatorlari-va-push-button-bilan-ishlash-1-qism" tabindex="-1">8-dars: Arduino UNO yordamida LED indikatorlari va push-button bilan ishlash (1-qism) <a class="header-anchor" href="#_8-dars-arduino-uno-yordamida-led-indikatorlari-va-push-button-bilan-ishlash-1-qism" aria-label="Permalink to &quot;8-dars: Arduino UNO yordamida LED indikatorlari va push-button bilan ishlash (1-qism)&quot;">​</a></h2><ol><li>Arduino <code>D2</code> piniga va <code>GND</code> ga Push-button ulang. <code>pinMode(2, INPUT_PULLUP)</code> sozlamasidan foydalaning.</li><li>Tugma holatini o&#39;qib, Serial Monitorga chiqaruvchi dastur yozing.</li><li>Sxemaga Pin 9 dagi LEDni qo&#39;shing va quyidagi xavfsizlik signalizatsiyasi mantiqini tuzing: <ul><li>Tugma bo&#39;sh turganda (eshik yopiq deb hisoblanadi): LED o&#39;chiq bo&#39;lsin;</li><li>Tugma bosilganda (eshik buzib ochildi): LED tez miltillab xavf signali bersin va Serial Monitorga &quot;DIQQAT: Eshik ochildi!&quot; matni uzatilsin.</li></ul></li></ol><hr><h2 id="_9-dars-arduino-uno-yordamida-led-indikatorlari-va-push-button-bilan-interaktiv-interfeys-2-qism" tabindex="-1">9-dars: Arduino UNO yordamida LED indikatorlari va push-button bilan interaktiv interfeys (2-qism) <a class="header-anchor" href="#_9-dars-arduino-uno-yordamida-led-indikatorlari-va-push-button-bilan-interaktiv-interfeys-2-qism" aria-label="Permalink to &quot;9-dars: Arduino UNO yordamida LED indikatorlari va push-button bilan interaktiv interfeys (2-qism)&quot;">​</a></h2><ol><li>1 ta Push-button va 1 ta LED yordamida to&#39;liq Toggle (trigged) kalitini dasturlang: tugma 1 marta bosilganda LED yonsin va yoniq qolsin, yana 1 marta bosilganda esa o&#39;chsin.</li><li>Dasturda nima sababdan <code>delay(50)</code> qo&#39;yilganini mexanik kontaktlarning dirillashi (Button Bounce) hodisasi misolida tushuntiring.</li><li>Sxemaga ikkinchi tugma va ikkinchi LED qo&#39;shing. Biri Qizil chiroqni, ikkinchisi Yashil chiroqni mustaqil boshqarsin. Ikkala chiroq bir-biriga xalaqit bermasdan ishlashini simulyatsiyada ko&#39;rsating.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>7-dars vazifasi (30 ball):</strong> 2 ta LED uchun mustaqil pinlar va alohida rezistorlar to&#39;g&#39;ri ulangani, ketma-ket va parallel farqi to&#39;g&#39;ri hisoblangani hamda mayoqcha kodi to&#39;g&#39;ri tuzilgani.</li><li><strong>8-dars vazifasi (35 ball):</strong> Push-button <code>INPUT_PULLUP</code> orqali to&#39;g&#39;ri ulangani, suzuvchi pin muammosi anglangani, Serial Monitor vositasida xabar chiqarish va <code>if-else</code> sharti to&#39;g&#39;ri ishlagani.</li><li><strong>9-dars vazifasi (35 ball):</strong> Toggle mantig&#39;i (<code>!ledState</code>), <code>lastButtonState</code> yordamida bosilish lahzasi aniqlangani, 50 ms Debounce filtri qo&#39;llangani va ko&#39;p tugmali tizim bekamu ko&#39;st ishlagani.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchilar Toggle dasturida tugma bosib turilganda tsikl tinimsiz aylanib ketmasligi uchun aynan holat o&#39;zgarishi (<code>reading != lastBtn</code>) shartidan foydalanganini tekshiring.</li></ul>',16))]),i("div",b,[i("h2",g,[l(t,{name:"list-checks"}),a[3]||(a[3]=d(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=n('<p><strong>Mavzular:</strong></p><ol><li>Elektron sxema asosida ikki LED lampaning ishlash prinsipi va ulanishi: ketma-ket vs parallel, Pin 9 va Pin 11, mustaqil vaqt tsikllari</li><li>Arduino UNO yordamida LED indikatorlari va push-button bilan ishlash (1-qism): 4 kontaktli tugma, suzuvchi pin, INPUT_PULLUP, Serial Monitor</li><li>Arduino UNO yordamida LED indikatorlari va push-button bilan interaktiv interfeys (2-qism): Toggle mantig&#39;i, Bounce va Debounce, ko&#39;p tugmali tizim</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Ikki LED va Parallel Boshqaruv</strong></td><td>Ketma-ket vs parallel ulanish qoidalari, alohida 220 Om rezistorlar, navbatma-navbat yoqish (Qizil 5s, Sariq 2s), stroboskop kodi</td><td>30 ball</td></tr><tr><td><strong>Push-Button va INPUT_PULLUP</strong></td><td>Tugma mexanikasi, suzuvchi pinni bartaraf etish, ichki rezistor bilan ulash, <code>digitalRead()</code>, <code>Serial.begin(9600)</code> bilan monitoring</td><td>35 ball</td></tr><tr><td><strong>Interaktiv Interfeys va Debounce</strong></td><td>Tugma bosilish lahzasini tutish (<code>lastButtonState</code>), dirillashni 50 ms filtr bilan tozalash, Toggle mantig&#39;i (<code>!ledState</code>), ko&#39;p tugmali boshqaruv</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Ikki LED &amp; Parallel (30)</th><th>Push-Button &amp; Serial (35)</th><th>Toggle &amp; Debounce (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar ko&#39;pincha Toggle mantig&#39;ini tushunishda qiynalishadi. Agar <code>buttonState == LOW</code> deb yozilsa, barmog&#39;ini tugmadan olguncha tsikl soniyasiga yuzlab marta aylanib, holat tasodifiy bo&#39;lib qoladi. Aynan holat o&#39;zgarishi (<code>reading != lastBtn</code>) va <code>delay(50)</code> zarurligini real osiloskop to&#39;lqinlari misolida ko&#39;rsatish juda foydali.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> 3 ta tugma va 3 ta LED yordamida &quot;Simon Says&quot; xotira o&#39;yini prototipini yaratish yoki tugma bosilganda har xil ohang chiqaruvchi passiv buzzer qo&#39;shish topshirig&#39;i berilishi mumkin.</li></ul>',11))])])}const _=o(h,[["render",k]]);export{z as __pageData,_ as default};
